// Campaign starts on 2026-09-03 (Day 1)
const startDate = new Date('2026-09-03T00:00:00.000Z');
const today = new Date();
today.setUTCHours(0, 0, 0, 0);

const diffMs = today.getTime() - startDate.getTime();
const dayNumber = Math.floor(diffMs / (24 * 60 * 60 * 1000)) + 1;

// Outside the 30-day window — stop the workflow
if (dayNumber < 1 || dayNumber > 30) {
  return [];
}

const topic = topics[dayNumber - 1];
return [{ json: { dayNumber, topic } }];
